const upsertPengaturan = `-- name: UpsertPengaturan :exec
INSERT INTO pengaturan (kunci, nilai, updated_at)
VALUES ($1, $2, now())
ON CONFLICT (kunci) DO UPDATE SET nilai = EXCLUDED.nilai, updated_at = now()
`

type UpsertPengaturanParams struct {
	Kunci string `json:"kunci"`
	Nilai string `json:"nilai"`
}

func (q *Queries) UpsertPengaturan(ctx context.Context, arg UpsertPengaturanParams) error {
	_, err := q.db.Exec(ctx, upsertPengaturan, arg.Kunci, arg.Nilai)
	return err
}
